INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "苗璘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：苗璘，吴右雄武军使、领水军者。", "biography": null, "status": "draft", "id": "a14ac394-f6eb-5bf5-bbf7-b8b68c346a7a"}, {"name": "王彦章（吴将）", "aliases": ["王彥章（吳將）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：王彦章（吴将），吴静江统军、领水军者。", "biography": null, "status": "draft", "id": "dd3b4583-fce8-59cf-ae24-6bfbee3b5173"}, {"name": "马殷", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁封马殷为楚王”中为受封者。", "biography": null, "status": "draft", "id": "7115610f-10b4-5211-b4a5-d2d089e6db83"}, {"name": "许德勋", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“荆南、楚军攻朗州，许德勋击败淮南援军”中为楚方统帅。", "biography": null, "status": "draft", "id": "22c59d0c-1661-5bcc-b43e-84d97c1ecda4"}, {"name": "高季昌", "aliases": ["高季兴"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“高季昌受命为荆南节度使”中为受任者。", "biography": null, "status": "draft", "id": "e1d9e2c4-6e41-5d7c-8d65-eb79a2407418"}, {"name": "李嗣源", "aliases": ["李亶", "后唐明宗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "biography": "李存勖麾下的重要将领。参与908年潞州解围，923年袭取郓州并率前军进入大梁。", "status": "draft", "id": "5d1886ff-b3ec-56f6-a154-b5633c294037"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "高从嗣", "aliases": ["高從嗣"], "era": "五代十国", "birth_year": null, "death_year": 928, "description": "《资治通鉴》卷276天成三年条所见人物：高从嗣，高季兴从子、云猛指挥使、挑战者。", "biography": null, "status": "draft", "id": "2173a3a8-a91e-55f5-a422-fafd6a99c293"}, {"name": "廖匡齐", "aliases": ["廖匡齊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：廖匡齐，副指挥使、出斗杀敌者。", "biography": null, "status": "draft", "id": "0d79e8f1-4787-5f81-84cc-50864386544a"}, {"name": "杜晏球", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：杜晏球。", "biography": null, "status": "draft", "id": "69b541c7-36ba-5aa1-a7dd-ed27fe48d03f"}, {"name": "朱弘昭", "aliases": ["硃弘昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：朱弘昭，太原人文思使、任东川副使。", "biography": null, "status": "draft", "id": "b16a5dfd-a78d-54bb-99a3-cd8af4e8da0b"}, {"name": "张虔钊", "aliases": ["張虔釗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张虔钊。", "biography": null, "status": "draft", "id": "b4b03cda-5958-57ef-b1ca-a5c8e1fb4985"}, {"name": "孟知祥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：孟知祥。", "biography": null, "status": "draft", "id": "07a6bbea-9699-5f43-aef3-481401e2ed5e"}, {"name": "毛重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：毛重威，左肃边指挥使、领三千人赴戍者。", "biography": null, "status": "draft", "id": "2108a64d-dc4c-5df6-b140-c389549daad0"}, {"name": "王宗寿", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：王宗寿。", "biography": null, "status": "draft", "id": "0fefb267-85f9-5dc1-9abb-ffe6a22bb5e9"}, {"name": "王宗衍", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：王宗衍。", "biography": null, "status": "draft", "id": "833f9aac-6321-5267-9e81-3e9756dfafc8"}, {"name": "安审通", "aliases": ["安審通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：安审通。", "biography": null, "status": "draft", "id": "8b318de0-b3e7-5558-9ffc-658558bd9126"}, {"n